export class Queue {
  constructor() {
    this.items = [];
  }

  enqueue(x) {
    this.items.push(x);
  }

  dequeue() {
    if (this.items.length === 0) throw new Error('empty');
    return this.items.shift();
  }

  get size() {
    return this.items.length;
  }
}
```

