{"path": "test/queue.test.js", "content": "import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Queue } from '../src/queue.js';

test('new queue is empty', () => {
  const q = new Queue();
  assert.equal(q.size, 0);
});

test('enqueue increases size', () => {
  const q = new Queue();
  q.enqueue(1);
  q.enqueue(2);
  assert.equal(q.size, 2);
});

test('dequeue returns items in FIFO order', () => {
  const q = new Queue();
  q.enqueue('a');
  q.enqueue('b');
  q.enqueue('c');
  assert.equal(q.dequeue(), 'a');
  assert.equal(q.dequeue(), 'b');
  assert.equal(q.size, 1);
  assert.equal(q.dequeue(), 'c');
  assert.equal(q.size, 0);
});

test('dequeue on empty queue returns undefined', () => {
  const q = new Queue();
  assert.equal(q.dequeue(), undefined);
  assert.equal(q.size, 0);
});

test('dequeue after draining returns undefined', () => {
  const q = new Queue();
  q.enqueue(1);
  q.dequeue();
  assert.doesNotThrow(() => q.dequeue());
  assert.equal(q.dequeue(), undefined);
});

test('falsy values are stored and returned', () => {
  const q = new Queue();
  q.enqueue(0);
  q.enqueue(null);
  assert.equal(q.dequeue(), 0);
  assert.equal(q.dequeue(), null);
  assert.equal(q.size, 0);
});
"}
